// src/doctor/doctorConsole.ts
var RESET = "\x1B[0m";
var BOLD = "\x1B[1m";
var DIM = "\x1B[2m";
var GREEN = "\x1B[32m";
var YELLOW = "\x1B[33m";
var RED = "\x1B[31m";
var CYAN = "\x1B[36m";
var MAGENTA = "\x1B[35m";
var BLUE = "\x1B[34m";
function colorEnabled() {
  if (process.env.NO_COLOR != null && process.env.NO_COLOR !== "") return false;
  if (process.env.FORCE_COLOR === "0") return false;
  return Boolean(process.stdout.isTTY) || process.env.FORCE_COLOR === "1";
}
function paint(code, text) {
  return colorEnabled() ? `${code}${text}${RESET}` : text;
}
function actionStyle(action) {
  switch (action) {
    case "created":
      return { symbol: "\u2713", label: "created", color: GREEN };
    case "updated":
      return { symbol: "\u2713", label: "corrected", color: GREEN };
    case "skipped":
      return { symbol: "\u25CB", label: "ok     ", color: DIM };
    case "failed":
      return { symbol: "\u2717", label: "failed ", color: RED };
    default:
      return { symbol: "\xB7", label: String(action), color: DIM };
  }
}
function pctBar(done, total) {
  const pct = total <= 0 ? 100 : Math.round(done / total * 100);
  const width = 12;
  const filled = Math.round(pct / 100 * width);
  const bar = `${"\u2588".repeat(filled)}${"\u2591".repeat(Math.max(0, width - filled))}`;
  const colored = paint(CYAN, `[${bar}]`) + " " + paint(BOLD + CYAN, `${String(pct).padStart(3)}%`);
  return colored;
}
function relPath(filePath, cwd) {
  if (!filePath) return "";
  if (filePath.startsWith(cwd)) {
    const r = filePath.slice(cwd.length).replace(/^[\\/]/, "");
    return r || ".";
  }
  return filePath;
}
function printDoctorReport(steps, opts) {
  const cwd = opts.cwd ?? process.cwd();
  const total = Math.max(steps.length, 1);
  console.log("");
  console.log(paint(BOLD + MAGENTA, "\u256D\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256E"));
  console.log(
    paint(BOLD + MAGENTA, "\u2502") + paint(BOLD + CYAN, `  ${opts.title}`.padEnd(44)) + paint(BOLD + MAGENTA, "\u2502")
  );
  console.log(paint(BOLD + MAGENTA, "\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256F"));
  if (opts.subtitle) {
    console.log(paint(DIM, `  ${opts.subtitle}`));
  }
  if (opts.language) {
    console.log(paint(BLUE, "  language ") + paint(BOLD, opts.language));
  }
  console.log(paint(DIM, `  project  ${cwd}`));
  console.log("");
  let done = 0;
  for (const step of steps) {
    done += 1;
    const { symbol, label, color } = actionStyle(step.action);
    const progress = pctBar(done, total);
    const sym = paint(BOLD + color, symbol);
    const act = paint(color, label);
    const name = paint(BOLD, step.step);
    const file = step.path ? paint(DIM, "  \u2192 ") + paint(CYAN, relPath(step.path, cwd)) : "";
    const detail = step.detail ? paint(DIM, `  (${step.detail})`) : "";
    let verb = "";
    if (step.action === "created") verb = paint(GREEN, " creating ");
    else if (step.action === "updated") verb = paint(GREEN, " fixing   ");
    else if (step.action === "skipped") verb = paint(DIM, " checking ");
    else verb = paint(RED, " error    ");
    console.log(`  ${progress}  ${sym} ${act}${verb}${name}${file}${detail}`);
  }
  console.log("");
  const failed = steps.filter((s) => s.action === "failed");
  const created = steps.filter((s) => s.action === "created").length;
  const updated = steps.filter((s) => s.action === "updated").length;
  const skipped = steps.filter((s) => s.action === "skipped").length;
  console.log(
    paint(DIM, "  summary ") + paint(GREEN, `${created} created`) + paint(DIM, " \xB7 ") + paint(GREEN, `${updated} corrected`) + paint(DIM, " \xB7 ") + paint(DIM, `${skipped} unchanged`) + (failed.length ? paint(DIM, " \xB7 ") + paint(RED, `${failed.length} failed`) : "")
  );
  console.log(`  ${pctBar(total, total)}  ${paint(BOLD, "complete")}`);
  console.log("");
  if (failed.length) {
    console.log(paint(BOLD + RED, "  \u2717 Doctor finished with errors \u2014 fix the failed steps and re-run."));
  } else {
    console.log(paint(BOLD + GREEN, "  \u2713 Doctor setup finished successfully."));
    if (opts.nextHint) {
      console.log(paint(YELLOW, `  \u2192 Next: ${opts.nextHint}`));
    }
    console.log(
      paint(DIM, "  tips  ") + paint(CYAN, "merv.emailable.html=true") + paint(DIM, " \u2192 emailable HTML on finish \xB7 ") + paint(CYAN, "npx merv show-report --host 0.0.0.0") + paint(DIM, " \u2192 LAN Share / Download")
    );
  }
  console.log("");
}

// src/doctor/ensureMervProperties.ts
import fs2 from "fs";
import path2 from "path";
var REQUIRED_KEYS = [
  { key: "merv.local", value: () => "true" },
  { key: "merv.report.folder", value: () => "./merv-reports/" },
  { key: "merv.regression_suite", value: (t) => t },
  { key: "merv.screenshot", value: () => "false" },
  { key: "merv.emailable.html", value: () => "false" }
];
function parsePropertiesFile(text) {
  const map = {};
  const order = [];
  const rawLines = text.split(/\r?\n/);
  for (const raw of rawLines) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const idx = line.indexOf("=");
    if (idx < 0) continue;
    const k = line.slice(0, idx).trim();
    const v = line.slice(idx + 1).trim();
    if (!(k in map)) order.push(k);
    map[k] = v;
  }
  return { order, map, rawLines };
}
function serializeMerged(rawLines, map, added) {
  const out = [...rawLines];
  while (out.length && out[out.length - 1] === "") out.pop();
  if (added.length) {
    if (out.length) out.push("");
    out.push("# Added by merv-doctor setup");
    for (const { key, value } of added) {
      out.push(`${key}=${value}`);
    }
  }
  out.push("");
  return out.join("\n");
}
function ensureMervProperties(cwd, opts = {}) {
  const filePath = path2.join(cwd, "merv.properties");
  const { name } = packageDeps(cwd);
  const suiteTitle = opts.suiteTitle?.trim() || name || "MERV Suite";
  const fresh = [
    "# Generated by merv-doctor setup",
    "merv.local=true",
    `merv.regression_suite=${suiteTitle}`,
    "merv.report.folder=./merv-reports/",
    "merv.screenshot=false",
    "merv.emailable.html=false",
    "",
    "# Action highlight video (stitches frames at 1/sec onto the testcase; step PNGs need merv.screenshot=true):",
    "# merv.video=true",
    "",
    "# Set true to write interactive emailable-report.html on every suite finish:",
    "# merv.emailable.html=true",
    "",
    "# Serve for Share / Download: npx merv show-report --host 0.0.0.0",
    "",
    "# Merv-Logs (NDJSON under merv-reports/log/): file logging is on by default.",
    "# merv.logger.file=false",
    "# Forward logs to another project's running show-report (combined Merv-Logs):",
    "# merv.log.server=http://127.0.0.1:6174",
    "# merv.log.source=my-project-name",
    "# (source = project name shown on the shared Merv-Logs page; defaults to package/folder name)",
    "# Playwright reporter step lines (default true). Set false when using merv-client-playwright/test:",
    "# merv.logger.reporter.steps=false",
    "",
    "# Cucumber + Playwright action rows + logs:",
    "# merv.playwright.actions=true",
    "",
    "# Server mode (optional):",
    "# merv.local=false",
    "# merv.server=https://merv.online/api/v1",
    "# merv.api_key=your-api-key",
    "# merv.parent_hierarchy=your-hierarchy-uuid",
    ""
  ].join("\n");
  if (!fs2.existsSync(filePath)) {
    writeTextFile(filePath, fresh);
    return { step: "merv.properties", action: "created", path: filePath };
  }
  if (opts.force) {
    writeTextFile(filePath, fresh);
    return {
      step: "merv.properties",
      action: "updated",
      path: filePath,
      detail: "rewrote (--force)"
    };
  }
  const text = fs2.readFileSync(filePath, "utf8");
  const { map, rawLines } = parsePropertiesFile(text);
  const added = [];
  for (const { key, value } of REQUIRED_KEYS) {
    if (!(key in map) || !String(map[key] ?? "").trim()) {
      added.push({ key, value: value(suiteTitle) });
    }
  }
  if (!added.length) {
    return {
      step: "merv.properties",
      action: "skipped",
      path: filePath,
      detail: "required keys already present (left existing values unchanged)"
    };
  }
  writeTextFile(filePath, serializeMerged(rawLines, map, added));
  return {
    step: "merv.properties",
    action: "updated",
    path: filePath,
    detail: `added missing keys: ${added.map((a) => a.key).join(", ")}`
  };
}

// src/doctor/setupCore.ts
var CUSTOM_REPORT_JS = `import { MervReport } from 'merv-client';

const report = await MervReport.open();

await report.createTest('Sample check', 'Created by merv-client doctor setup');
await report.info('Replace this script with your real checks.');
await report.testdata('Example payload', JSON.stringify({ ok: true }));
await report.validation('Status', 'ok', 'ok');

await report.finalize();
console.log('Report written under merv.report.folder \u2014 run: npx merv show-report');
`;
var CUSTOM_REPORT_TS = `import { MervReport } from 'merv-client';

async function main(): Promise<void> {
  const report = await MervReport.open();

  await report.createTest('Sample check', 'Created by merv-client doctor setup');
  await report.info('Replace this script with your real checks.');
  await report.testdata('Example payload', JSON.stringify({ ok: true }));
  await report.validation('Status', 'ok', 'ok');

  await report.finalize();
  console.log('Report written under merv.report.folder \u2014 run: npx merv show-report');
}

main().catch((err: unknown) => {
  console.error(err);
  process.exit(1);
});
`;
var TSCONFIG = {
  compilerOptions: {
    target: "ES2022",
    module: "NodeNext",
    moduleResolution: "NodeNext",
    strict: true,
    esModuleInterop: true,
    skipLibCheck: true,
    types: ["node"]
  },
  include: ["scripts/**/*.ts"]
};
var JSCONFIG = {
  compilerOptions: {
    module: "ESNext",
    moduleResolution: "node",
    target: "ES2022",
    checkJs: false
  },
  include: ["scripts/**/*.js", "scripts/**/*.mjs"]
};
function setupCore(cwd, opts = {}) {
  const force = !!opts.force;
  const language = opts.language && opts.language !== "auto" ? opts.language : detectLanguage(cwd);
  const sampleScript = opts.sampleScript !== false;
  const steps = [];
  steps.push(ensureMervProperties(cwd, { force, suiteTitle: opts.suiteTitle }));
  const { pkg, pkgPath } = packageDeps(cwd);
  if (pkg) {
    let changed = false;
    const details = [];
    const scripts = { ...pkg.scripts || {} };
    if (!scripts["show-report"]) {
      scripts["show-report"] = "merv show-report";
      changed = true;
      details.push("added show-report");
    }
    if (!scripts["show-logs"]) {
      scripts["show-logs"] = "merv show-logs";
      changed = true;
      details.push("added show-logs");
    }
    if (sampleScript) {
      const want = language === "typescript" ? "npx tsx scripts/custom-report.ts" : "node scripts/custom-report.mjs";
      if (!scripts["merv:report"]) {
        scripts["merv:report"] = want;
        changed = true;
        details.push("added merv:report");
      }
    }
    if (changed) {
      pkg.scripts = scripts;
      writeJsonFile(pkgPath, pkg);
      steps.push({
        step: "package.json scripts",
        action: "updated",
        path: pkgPath,
        detail: `${details.join(", ")} (left other package.json fields unchanged)`
      });
    } else {
      steps.push({
        step: "package.json",
        action: "skipped",
        path: pkgPath,
        detail: "MERV scripts already present"
      });
    }
  } else {
    steps.push({
      step: "package.json",
      action: "failed",
      detail: "No package.json in this folder \u2014 run npm init first"
    });
  }
  if (language === "typescript") {
    const tsPath = path3.join(cwd, "tsconfig.json");
    if (fs3.existsSync(tsPath) && !force) {
      steps.push({
        step: "tsconfig.json",
        action: "skipped",
        path: tsPath,
        detail: "already exists"
      });
    } else {
      const action = writeFileSmart(tsPath, JSON.stringify(TSCONFIG, null, 2), force);
      steps.push({ step: "tsconfig.json", action, path: tsPath });
    }
  } else {
    const jsPath = path3.join(cwd, "jsconfig.json");
    if (fs3.existsSync(jsPath) && !force) {
      steps.push({
        step: "jsconfig.json",
        action: "skipped",
        path: jsPath,
        detail: "already exists"
      });
    } else if (!fs3.existsSync(path3.join(cwd, "tsconfig.json"))) {
      const action = writeFileSmart(jsPath, JSON.stringify(JSCONFIG, null, 2), force);
      steps.push({ step: "jsconfig.json", action, path: jsPath });
    }
  }
  if (sampleScript) {
    if (language === "typescript") {
      const scriptPath = path3.join(cwd, "scripts", "custom-report.ts");
      steps.push({
        step: "scripts/custom-report.ts",
        action: writeFileSmart(scriptPath, CUSTOM_REPORT_TS, force),
        path: scriptPath
      });
    } else {
      const scriptPath = path3.join(cwd, "scripts", "custom-report.mjs");
      steps.push({
        step: "scripts/custom-report.mjs",
        action: writeFileSmart(scriptPath, CUSTOM_REPORT_JS, force),
        path: scriptPath
      });
    }
  }
  steps.push({
    step: "next steps",
    action: "skipped",
    detail: language === "typescript" ? "npm i -D typescript tsx @types/node && npm run merv:report && npx merv show-report" : "npm run merv:report && npx merv show-report"
  });
  return steps;
}
function printCoreDoctorResult(language, steps) {
  printDoctorReport(steps, {
    title: "merv-client doctor setup",
    subtitle: "Core / custom report only \u2014 heal + merge MERV bits",
    language: `${language} (custom report / core)`,
    nextHint: "Playwright \u2192 npx merv-client-playwright doctor setup \xB7 Cucumber \u2192 npx merv-client-cucumber doctor setup"
  });
}
function resolveCoreLanguage(cwd, language) {
  return language && language !== "auto" ? language : detectLanguage(cwd);
}

// src/cli/mervDoctor.ts
function printHelp() {
  console.log(`Usage:
  merv-doctor setup [options]

Core-only scaffold (same as \`npx merv-client doctor setup\`):
  merv.properties, jsconfig/tsconfig, sample custom-report script

Prefer package CLIs for frameworks:
  npx merv-client doctor setup
  npx merv-client-playwright doctor setup
  npx merv-client-cucumber doctor setup

Options:
  --typescript / --javascript
  --force
  --suite-title <name>
  --no-sample
  -h, --help
`);
}
function parseArgs(argv) {
  const out = { help: false, force: false, sampleScript: true };
  const args = argv.slice(2);
  let i = 0;
  if (args[0] === "doctor") i = 1;
  if (args.length === 0 || args.includes("-h") || args.includes("--help")) {
    out.help = true;
    return out;
  }
  out.command = args[i++];
  for (; i < args.length; i++) {
    const a = args[i];
    if (a === "--force") out.force = true;
    else if (a === "--typescript") out.language = "typescript";
    else if (a === "--javascript") out.language = "javascript";
    else if (a === "--no-sample") out.sampleScript = false;
    else if (a === "--suite-title") {
      out.suiteTitle = args[++i];
      if (!out.suiteTitle) throw new Error("Missing value for --suite-title");
    } else if (a.startsWith("-")) {
      throw new Error(`Unknown option: ${a}`);
    } else {
      throw new Error(`Unexpected argument: ${a}`);
    }
  }
  return out;
}
async function main() {
  let parsed;
  try {
    parsed = parseArgs(process.argv);
  } catch (e) {
    console.error(`[merv-doctor] ${e instanceof Error ? e.message : e}`);
    printHelp();
    process.exitCode = 1;
    return;
  }
  if (parsed.help || !parsed.command) {
    printHelp();
    return;
  }
  if (parsed.command !== "setup") {
    console.error(`[merv-doctor] Unknown command: ${parsed.command}`);
    printHelp();
    process.exitCode = 1;
    return;
  }
  const cwd = process.cwd();
  const language = resolveCoreLanguage(cwd, parsed.language ?? "auto");
  try {
    const steps = setupCore(cwd, {
      force: parsed.force,
      language,
      suiteTitle: parsed.suiteTitle,
      sampleScript: parsed.sampleScript
    });
    printCoreDoctorResult(language, steps);
    if (steps.some((s) => s.action === "failed")) process.exitCode = 1;
  } catch (e) {
    console.error(`[merv-doctor] ${e instanceof Error ? e.message : e}`);
    process.exitCode = 1;
  }
}
void main();
